function routeFromHash(){let raw='home';try{raw=decodeURIComponent((location.hash||'#home').slice(1))}catch{history.replaceState(null,'','#home');return'home'}return validRoute(raw)?raw:'home'}
function go(view,replace=false){if(!validRoute(view))view='home';if(view==='admin'&&!S.admin){toast('Esta sección es exclusiva de la administración global.','bad');return}pendingRouteFocus=true;const next='#'+encodeURIComponent(view).replace(/%3A/g,':');if(location.hash===next){S.view=view;render();window.scrollTo({top:0,behavior:'smooth'});return}if(replace){history.replaceState(null,'',next);S.view=view;render()}else location.hash=next}
let toastTimer,lastToastMessage='',lastToastAt=0;function toast(message,type=''){const host=$('#toastHost');if(!host)return;const msg=String(message||''),now=Date.now();if(msg===lastToastMessage&&now-lastToastAt<5000)return;lastToastMessage=msg;lastToastAt=now;host.replaceChildren();const el=document.createElement('div');el.className='toast '+type;el.textContent=msg;host.appendChild(el);clearTimeout(toastTimer);toastTimer=setTimeout(()=>{host.replaceChildren();if(lastToastMessage===msg)lastToastMessage=''},4200)}
function setNetworkBadge(){const el=$('#netBadge');if(!el)return;S.online=navigator.onLine;el.hidden=S.online;if(!S.online)el.textContent='Sin conexión · algunas funciones no estarán disponibles'}
function friendlyError(e,fallback='Ocurrió un error inesperado.'){const m=String(e?.message||'');if(e?.name==='AbortError'||/aborted|timeout/i.test(m))return'La conexión tardó demasiado. Intenta nuevamente.';if(/Failed to fetch|NetworkError/i.test(m))return'No se pudo conectar con el servidor.';return m||fallback}

let refreshPromise=null;
function persistSession(data){
 S.token=data?.access_token||'';
 S.refreshToken=data?.refresh_token||S.refreshToken||'';
 const expiresIn=Number(data?.expires_in||3600);
 S.tokenExpiresAt=S.token?Date.now()+Math.max(0,expiresIn-60)*1000:0;
 if(S.token)localStorage.setItem('nlobi_token',S.token);else localStorage.removeItem('nlobi_token');
 if(S.refreshToken)localStorage.setItem('nlobi_refresh_token',S.refreshToken);else localStorage.removeItem('nlobi_refresh_token');
 if(S.tokenExpiresAt)localStorage.setItem('nlobi_token_expires_at',String(S.tokenExpiresAt));else localStorage.removeItem('nlobi_token_expires_at')
}
function clearSession(){
 S.token='';S.refreshToken='';S.tokenExpiresAt=0;
 localStorage.removeItem('nlobi_token');localStorage.removeItem('nlobi_refresh_token');localStorage.removeItem('nlobi_token_expires_at')
}
function consumeAuthCallback(){
 const raw=(location.hash||'').slice(1);
 if(!raw||(!raw.includes('access_token=')&&!raw.includes('error_description=')))return false;
 const p=new URLSearchParams(raw);
 const err=p.get('error_description')||p.get('error');
 if(err){
  sessionStorage.setItem('nlobi_auth_notice','error:'+err);
  history.replaceState(null,'',location.pathname+location.search+'#auth');
  return true
 }
 const access_token=p.get('access_token');
 if(!access_token)return false;
 persistSession({access_token,refresh_token:p.get('refresh_token')||'',expires_in:Number(p.get('expires_in')||3600)});
 sessionStorage.setItem('nlobi_auth_notice','ok:'+(p.get('type')==='signup'?'Correo verificado correctamente.':'Sesión confirmada correctamente.'));
 history.replaceState(null,'',location.pathname+location.search+'#home');
 return true
}

async function refreshSession(){
 if(!S.refreshToken)throw new Error('La sesión expiró. Inicia sesión nuevamente.');
 if(refreshPromise)return refreshPromise;
 refreshPromise=(async()=>{
  const ctrl=new AbortController(),timer=setTimeout(()=>ctrl.abort(),7000);
  try{
   const r=await fetch(URL+'/auth/v1/token?grant_type=refresh_token',{method:'POST',headers:{apikey:KEY,'Content-Type':'application/json'},body:JSON.stringify({refresh_token:S.refreshToken}),signal:ctrl.signal});
   if(!r.ok)throw new Error((await r.text()).slice(0,220)||'No se pudo renovar la sesión.');
   const data=await r.json();persistSession(data);return data
  }finally{clearTimeout(timer)}
 })();
 try{return await refreshPromise}finally{refreshPromise=null}
}
async function ensureFreshSession(){
 if(S.token&&S.refreshToken&&S.tokenExpiresAt&&Date.now()>=S.tokenExpiresAt)await refreshSession()
}
async function req(path,opt={}){
 const doFetch=async()=>{
  const ctrl=new AbortController(),timer=setTimeout(()=>ctrl.abort(),7000);
  const h={'apikey':KEY,'Content-Type':'application/json',...(S.token?{'Authorization':'Bearer '+S.token}:{}),...(opt.headers||{})};
  try{return await fetch(URL+path,{...opt,headers:h,signal:ctrl.signal})}finally{clearTimeout(timer)}
 };
 if(!path.startsWith('/auth/v1/token'))await ensureFreshSession();
 let r=await doFetch();
 if(r.status===401&&S.refreshToken&&!opt.__retried&&!path.startsWith('/auth/v1/token')){
  try{await refreshSession();r=await req(path,{...opt,__retried:true})}catch(e){clearSession();throw e}
 }
 return r
}
async function jreq(path,opt={}){const r=await req(path,opt);if(!r.ok)throw new Error((await r.text()).slice(0,220)||r.statusText);const tx=await r.text();return tx?JSON.parse(tx):null}
async function storageUpload(file,path,upsert=true){
 if(!S.token)throw new Error('Debes iniciar sesión para subir archivos.');
 await ensureFreshSession();
 if(!file||!/^image\/(jpeg|png|webp|gif)$/i.test(file.type||''))throw new Error('Usa una imagen JPG, PNG, WEBP o GIF.');
 if(file.size>8388608)throw new Error('La imagen supera el límite de 8 MB.');
 const clean=path.split('/').map(x=>encodeURIComponent(x)).join('/');
 const r=await fetch(`${URL}/storage/v1/object/nlobi-media/${clean}`,{method:'POST',headers:{apikey:KEY,Authorization:'Bearer '+S.token,'Content-Type':file.type,'x-upsert':upsert?'true':'false','cache-control':'3600'},body:file});
 if(!r.ok)throw new Error((await r.text()).slice(0,250)||'No se pudo subir la imagen.');
 return storagePublicUrl(path)
}
function storagePublicUrl(path){return `${URL}/storage/v1/object/public/nlobi-media/${path.split('/').map(x=>encodeURIComponent(x)).join('/')}`}
function storagePathFromPublicUrl(url){const s=String(url||''),mark='/storage/v1/object/public/nlobi-media/';const i=s.indexOf(mark);if(i<0)return null;try{return s.slice(i+mark.length).split('/').map(decodeURIComponent).join('/')}catch{return null}}
async function deleteOldMediaIfUnused(url){const path=storagePathFromPublicUrl(url);if(!path)return;try{const rows=await jreq('/rest/v1/rpc/media_usage_for_paths',{method:'POST',body:JSON.stringify({p_paths:[path]})})||[];if(Number(rows?.[0]?.reference_count||0)===0)await storageDelete(path)}catch(e){console.warn('No se pudo limpiar multimedia anterior',e)}}
function mediaStableName(kind,file){return `${kind}.${storageExt(file)}`}
async function testPngFile(size,name){const canvas=document.createElement('canvas');canvas.width=size;canvas.height=size;const ctx=canvas.getContext('2d');ctx.fillStyle=size===1?'#ffd400':'#111111';ctx.fillRect(0,0,size,size);const blob=await new Promise((resolve,reject)=>canvas.toBlob(b=>b?resolve(b):reject(new Error('No se pudo generar PNG de prueba.')),'image/png'));return new File([blob],name,{type:'image/png'})}
function storageExt(file){const m={'image/jpeg':'jpg','image/png':'png','image/webp':'webp','image/gif':'gif'};return m[file?.type]||'img'}
function storageName(prefix,file){return `${prefix}-${Date.now().toString(36)}-${Math.random().toString(36).slice(2,8)}.${storageExt(file)}`}

async function storageListFolder(prefix,offset=0,limit=200){await ensureFreshSession();const r=await fetch(`${URL}/storage/v1/object/list/nlobi-media`,{method:'POST',headers:{apikey:KEY,Authorization:'Bearer '+S.token,'Content-Type':'application/json'},body:JSON.stringify({prefix,limit,offset,sortBy:{column:'updated_at',order:'desc'}})});if(!r.ok)throw new Error((await r.text()).slice(0,250)||'No se pudo listar Storage.');return await r.json()}
async function storageWalk(prefix,depth=0){if(depth>8)return[];const out=[],pageSize=200;let offset=0;while(true){const rows=await storageListFolder(prefix,offset,pageSize);for(const x of rows||[]){const path=prefix?`${prefix}/${x.name}`:x.name;const isFolder=!x.id&&(!x.metadata||Object.keys(x.metadata||{}).length===0);if(isFolder)out.push(...await storageWalk(path,depth+1));else if(/\.(jpe?g|png|webp|gif)$/i.test(x.name||''))out.push({name:x.name,path,size:x.metadata?.size||0,mimetype:x.metadata?.mimetype||'',updated_at:x.updated_at||x.created_at||''})}if(!rows||rows.length<pageSize)break;offset+=pageSize}return out}
async function storageDelete(path){
 await ensureFreshSession();
 const r=await fetch(`${URL}/storage/v1/object/nlobi-media`,{method:'DELETE',headers:{apikey:KEY,Authorization:'Bearer '+S.token,'Content-Type':'application/json'},body:JSON.stringify({prefixes:[path]})});
 if(!r.ok)throw new Error((await r.text()).slice(0,250)||'No se pudo eliminar el archivo.');
 const result=await r.json().catch(()=>null);
 const deleted=Array.isArray(result)?result:Array.isArray(result?.data)?result.data:null;
 if(deleted&&!deleted.some(item=>typeof item==='string'?item===path:item?.name===path||item?.path===path)){
  throw new Error('Supabase no eliminó el archivo. Puede estar protegido por permisos o por una referencia activa.');
 }
 const folder=path.slice(0,path.lastIndexOf('/')),filename=path.slice(path.lastIndexOf('/')+1);
 const remaining=await storageListFolder(folder,0,200);
 if(remaining.some(x=>x.name===filename))throw new Error('El archivo sigue en Storage. Revisa permisos y referencias antes de volver a intentar.');
 return true
}
function dataUrlToBlob(dataUrl){
 const m=String(dataUrl||'').match(/^data:(image\/(?:png|jpeg|jpg|webp|gif));base64,(.+)$/i);if(!m)return null;
 const bin=atob(m[2]),bytes=new Uint8Array(bin.length);for(let i=0;i<bin.length;i++)bytes[i]=bin.charCodeAt(i);
 return new Blob([bytes],{type:m[1].replace('jpg','jpeg')})
}
async function materializeImportedImages(blocks,groupId,sectionKey,uploadedPaths=[]){
 const out=[];let n=0;
 for(const raw of blocks||[]){
  const b=normalizeImportBlock(raw);
  if(b.type==='image'&&/^data:image\//i.test(b.url||'')){
   const blob=dataUrlToBlob(b.url);
   if(blob){n++;const file=new File([blob],`import-${n}.${storageExt(blob)}`,{type:blob.type});const path=`teams/${groupId}/imports/${sectionKey}/${storageName('image',file)}`;b.url=await storageUpload(file,path,false);uploadedPaths.push(path)}
  }
  out.push(b)
 }
 return out
}

