function existingVolumeCoverCandidate(volume){
 const sections=[...(volume?.sections||[])].sort((a,b)=>(Number(a.sort_order)||0)-(Number(b.sort_order)||0));
 for(const section of sections){
  const blocks=Array.isArray(section.content)?section.content:[];
  for(const block of blocks){
   if(block?.type!=='image'||!block.url)continue;
   const url=String(block.url).trim();
   if(/^https:\/\//i.test(url)&&safeMediaUrl(url)!=='#')return url;
  }
 }
 return '';
}
async function recoverExistingVolumeCover(volumeId){
 const P=S.studioProject,volume=P?.volumes?.find(v=>v.id===volumeId);
 if(!P||!volume)return;
 if(volume.cover_url){toast('Este volumen ya tiene portada; no se modificó.','bad');return}
 const candidate=existingVolumeCoverCandidate(volume);
 if(!candidate){toast('No se encontró una imagen conservada en los capítulos. Importa nuevamente el archivo original para recuperarla.','bad');return}
 try{
  await jreq('/rest/v1/volumes?id=eq.'+volume.id+'&cover_url=is.null',{method:'PATCH',headers:{Prefer:'return=minimal'},body:JSON.stringify({cover_url:candidate,updated_at:new Date().toISOString()})});
  if(P.novels?.id&&!P.novels.cover_url){
   try{await jreq('/rest/v1/novels?id=eq.'+P.novels.id+'&cover_url=is.null',{method:'PATCH',headers:{Prefer:'return=minimal'},body:JSON.stringify({cover_url:candidate})})}catch(e){console.warn('No se pudo asignar portada general',e)}
  }
  S.recoverCoverVolumeId=null;
  await refreshStudioProject();
  toast('Portada recuperada del contenido existente.','ok')
 }catch(e){toast(friendlyError(e,'No se pudo recuperar la portada.'),'bad')}
}
