function importCanonicalText(v){return normalizeImportedText(String(v||'')).normalize('NFKC').toLowerCase().replace(/\s+/g,' ').trim()}
function importFingerprint(title,blocks){const raw=importCanonicalText(title)+'\n'+importCanonicalText(blocksToPlainText((blocks||[]).map(normalizeImportBlock)));let h=2166136261;for(let i=0;i<raw.length;i++){h^=raw.charCodeAt(i);h=Math.imul(h,16777619)}return(h>>>0).toString(36)+':'+raw.length}
async function rollbackImportedPaths(paths){let failed=0;for(const path of [...new Set(paths||[])].reverse())try{await storageDelete(path)}catch{failed++}return failed}
async function publishImportedVolume(){const I=S.importState;if(!I.savedVolumeId||I.busy)return;I.busy=true;render();try{await jreq('/rest/v1/rpc/publish_volume_with_sections',{method:'POST',body:JSON.stringify({p_volume_id:I.savedVolumeId})});I.message='Volumen publicado con sus capítulos.';await loadCatalog();toast(I.message,'ok')}catch(e){I.message=friendlyError(e,'No se pudo publicar el volumen.')}finally{I.busy=false;render()}}
async function openImportedVolume(){const I=S.importState;if(!I.savedVolumeId)return;S.studioProject=await loadStudioProject(I.translationId);S.studioEditVolumeId=I.savedVolumeId;go('studio:project:'+I.translationId)}
async function saveImportDrafts(publishAfter=false){const I=S.importState;if(I.busy)return;I.busy=true;I.message='';render();let jobId=null,uploadedPaths=[],backup=[],volume=null,sectionsPersisted=false;try{syncImportFields();const tr=S.studioTranslations.find(x=>x.id===I.translationId);if(!tr)throw new Error('Proyecto no disponible.');const gid=tr.group_id||tr.translator_groups?.id;if(!teamCan(gid,'import'))throw new Error('No tienes permiso para importar archivos.');if(publishAfter&&!teamCan(gid,'publish'))throw new Error('No tienes permiso para publicar.');const job=await jreq('/rest/v1/import_jobs',{method:'POST',headers:{Prefer:'return=representation'},body:JSON.stringify({group_id:gid,created_by:S.user.id,filename:I.name,file_type:I.type,status:'processing',result:{section_count:I.sections.length}})});jobId=job?.[0]?.id||null;let vols=await jreq('/rest/v1/volumes?translation_id=eq.'+I.translationId+'&volume_number=eq.'+encodeURIComponent(I.volumeNumber)+'&select=id,title,volume_number&limit=1'),existing=[];volume=vols?.[0];if(!volume){const created=await jreq('/rest/v1/volumes',{method:'POST',headers:{Prefer:'return=representation'},body:JSON.stringify({translation_id:I.translationId,volume_number:Number(I.volumeNumber),title:I.volumeTitle||null,status:'draft'})});volume=created?.[0]}else{existing=await jreq('/rest/v1/sections?volume_id=eq.'+volume.id+'&select=id,section_type,section_number,title,content,sort_order,status,published_at,updated_at&order=sort_order.asc')||[];backup=existing.map(x=>({section_type:x.section_type,section_number:x.section_number,title:x.title,content:x.content,sort_order:x.sort_order,status:x.status,published_at:x.published_at}));if(existing.length&&I.existingAction==='replace'){if(!confirm('Este volumen ya tiene '+existing.length+' secciones. Se guardará un respaldo técnico en el registro de importación antes de reemplazarlas. ¿Continuar?'))throw new Error('Importación cancelada.');if(jobId)await jreq('/rest/v1/import_jobs?id=eq.'+jobId,{method:'PATCH',headers:{Prefer:'return=minimal'},body:JSON.stringify({result:{section_count:I.sections.length,backup_volume_id:volume.id,backup_sections:backup},updated_at:new Date().toISOString()})});await jreq('/rest/v1/sections?volume_id=eq.'+volume.id,{method:'DELETE',headers:{Prefer:'return=minimal'}});existing=[]}}if(!volume?.id)throw new Error('No se pudo resolver el volumen.');if(I.useDetectedCover&&I.detectedCover){const current=await jreq('/rest/v1/volumes?id=eq.'+volume.id+'&select=cover_url&limit=1');if(I.existingAction==='replace'||!current?.[0]?.cover_url){const blob=dataUrlToBlob(I.detectedCover);if(blob){const f=new File([blob],'portada-importada.'+storageExt(blob),{type:blob.type});const path='teams/'+gid+'/volumes/'+volume.id+'/'+storageName('imported-cover',f);const url=await storageUpload(f,path,false);uploadedPaths.push(path);await jreq('/rest/v1/volumes?id=eq.'+volume.id,{method:'PATCH',headers:{Prefer:'return=minimal'},body:JSON.stringify({cover_url:url,updated_at:new Date().toISOString()})});const translation=await jreq('/rest/v1/translations?id=eq.'+I.translationId+'&select=novel_id&limit=1');const novelId=translation?.[0]?.novel_id;if(novelId){const novel=await jreq('/rest/v1/novels?id=eq.'+novelId+'&select=cover_url&limit=1');if(!novel?.[0]?.cover_url||(I.existingAction==='replace'&&novel?.[0]?.cover_url===current?.[0]?.cover_url))try{await jreq('/rest/v1/novels?id=eq.'+novelId,{method:'PATCH',headers:{Prefer:'return=minimal'},body:JSON.stringify({cover_url:url})})}catch(e){console.warn('La portada del volumen se guardó; no se pudo actualizar la portada general',e)}}}}}let nextNumber=existing.reduce((m,x)=>Math.max(m,Number(x.section_number)||0),0),nextSort=existing.reduce((m,x)=>Math.max(m,Number(x.sort_order)||0),0),duplicates=0;const known=new Set(existing.map(x=>importFingerprint(x.title,Array.isArray(x.content)?x.content:[]))),payload=[];for(let i=0;i<I.sections.length;i++){const x=I.sections[i],raw=(x.blocks?.length?x.blocks.map(normalizeImportBlock):textBlocks(x.body)),fingerprint=importFingerprint(x.title,raw);if(I.existingAction==='append'&&known.has(fingerprint)){duplicates++;continue}known.add(fingerprint);const content=await materializeImportedImages(raw,gid,'volume-'+volume.id+'-section-'+(nextSort+1),uploadedPaths);nextNumber++;nextSort++;payload.push({volume_id:volume.id,section_type:x.section_type,section_number:nextNumber,title:x.title,content,sort_order:nextSort,status:'draft'})}if(payload.length){await jreq('/rest/v1/sections',{method:'POST',headers:{Prefer:'return=minimal'},body:JSON.stringify(payload)});sectionsPersisted=true;}let fontNotice='';if(I.type==='epub'&&I.file){try{const fonts=await uploadEmbeddedEpubFonts(I.file,I.epubFonts,gid,volume.id,uploadedPaths);if(fonts.length||I.existingAction==='replace'){await jreq('/rest/v1/volumes?id=eq.'+volume.id,{method:'PATCH',headers:{Prefer:'return=minimal'},body:JSON.stringify({epub_fonts:fonts,epub_font_url:fonts[0]?.url||null,epub_font_family:fonts[0]?.family||null})})}}catch(err){fontNotice=' Algunas fuentes originales no pudieron guardarse; los capítulos sí se conservaron.';console.warn('Fuentes EPUB:',err)}}if(jobId)await jreq('/rest/v1/import_jobs?id=eq.'+jobId,{method:'PATCH',headers:{Prefer:'return=minimal'},body:JSON.stringify({status:'completed',result:{section_count:payload.length,skipped_duplicates:duplicates,volume_id:volume.id,translation_id:I.translationId,existing_action:I.existingAction,backup_sections:I.existingAction==='replace'?backup:undefined},updated_at:new Date().toISOString()})});if(publishAfter){const importedQuality=studioVolumeQuality({title:I.volumeTitle||volume.title,cover_url:I.useDetectedCover?I.detectedCover||volume.cover_url:volume.cover_url,sections:I.sections.map(x=>({title:x.title,content:x.blocks||[]}))});if(!approveStudioQuality(importedQuality,'el volumen importado')){publishAfter=false;fontNotice+=' La publicación no se realizó; el contenido quedó como borrador.'}}if(publishAfter)await jreq('/rest/v1/rpc/publish_volume_with_sections',{method:'POST',body:JSON.stringify({p_volume_id:volume.id})});I.savedVolumeId=volume.id;try{localStorage.removeItem(importCheckpointKey())}catch{}I.busy=false;I.message=(publishAfter?'Volumen publicado. ':'Importación completada: ')+payload.length+' secciones guardadas'+(duplicates?' · '+duplicates+' duplicado(s) exacto(s) omitido(s)':'')+'.'+fontNotice;render()}catch(e){const rollbackFailed=sectionsPersisted?0:await rollbackImportedPaths(uploadedPaths);if(jobId)try{await jreq('/rest/v1/import_jobs?id=eq.'+jobId,{method:'PATCH',headers:{Prefer:'return=minimal'},body:JSON.stringify({status:'failed',result:{error:String(e?.message||e).slice(0,500),rolled_back_files:uploadedPaths.length-rollbackFailed,rollback_failed:rollbackFailed,backup_volume_id:volume?.id||null,backup_sections:backup.length?backup:undefined},updated_at:new Date().toISOString()})})}catch{}I.busy=false;I.message=friendlyError(e,'No se pudo guardar la importación.')+(rollbackFailed?' Algunos archivos temporales no pudieron limpiarse.':'');render()}}


function setReaderPref(k,v){const open=!!$('#readerSettings')?.open;S.readerPrefs[k]=v;const keys={fontSize:'reader_font',theme:'reader_theme',width:'reader_width',lineHeight:'reader_line_height',fontFamily:'reader_font_family',paragraphSpace:'reader_paragraph_space'};localStorage.setItem(keys[k]||('reader_'+k),String(v));render();if(open&&$('#readerSettings'))$('#readerSettings').open=true}
function resetReaderPrefs(){S.readerPrefs={theme:'light',fontSize:18,width:'normal',lineHeight:'comfortable',fontFamily:'original',paragraphSpace:'normal',indent:'none',align:'left',contrast:'standard',images:'show'};['reader_theme','reader_font','reader_width','reader_line_height','reader_font_family','reader_paragraph_space','reader_indent','reader_align','reader_contrast','reader_images'].forEach(k=>localStorage.removeItem(k));render();toast('Preferencias de lectura restablecidas.','ok')}
function isFollowing(type,id){return (S.follows||[]).some(f=>f.target_type===type&&f.target_id===id)}
function followNovelButton(id){if(!id||!S.user)return '';const following=isFollowing('translation',id);return `<button type="button" class="btn followNovelButton ${following?'following':''}" data-follow-type="translation" data-follow-id="${esc(id)}" aria-pressed="${following?'true':'false'}">${following?'✓ Siguiendo · Avisos activados':'＋ Seguir novela'}</button>`}
function unreadNovelUpdates(id){return (S.notes||[]).filter(n=>n.notification_type==='new_publication'&&n.translation_id===id&&!n.read_at).length}
async function loadFollows(){if(!S.user){S.follows=[];return}S.follows=await jreq(`/rest/v1/follows?user_id=eq.${S.user.id}&select=target_type,target_id,created_at`)||[]}
async function toggleFollow(type,id){try{if(!S.user){go('auth');return}if(isFollowing(type,id)){await jreq(`/rest/v1/follows?user_id=eq.${S.user.id}&target_type=eq.${type}&target_id=eq.${id}`,{method:'DELETE',headers:{Prefer:'return=minimal'}})}else{await jreq('/rest/v1/follows',{method:'POST',headers:{Prefer:'return=minimal'},body:JSON.stringify({user_id:S.user.id,target_type:type,target_id:id})})}await loadFollows();render();toast(isFollowing(type,id)?'Ahora recibirás avisos de las nuevas publicaciones.':'Dejaste de seguir esta publicación.','ok')}catch(e){toast(friendlyError(e),'bad')}}
async function loadVolumeComments(volumeId){const D=S.currentDetail,volume=D?.volumes?.find(v=>v.id===volumeId),ids=(volume?.sections||[]).filter(x=>x.status==='published').map(x=>x.id);S.readerComments=[];if(!ids.length)return;const rows=await jreq('/rest/v1/comments?section_id=in.('+ids.join(',')+')&select=id,section_id,user_id,parent_id,body,is_spoiler,created_at,profiles(id,username,display_name),comment_reactions(user_id,reaction)&order=created_at.asc');S.readerComments=(rows||[]).map(c=>({...c,like_count:(c.comment_reactions||[]).filter(r=>r.reaction==='like').length,liked_by_me:!!S.user&&(c.comment_reactions||[]).some(r=>r.user_id===S.user.id&&r.reaction==='like')}))}
async function openVolumeComments(volumeId,firstId){if(S.volumeCommentsId===volumeId){S.volumeCommentsId=null;render();return}S.volumeCommentsId=volumeId;S.volumeCommentSectionId=firstId;try{await loadVolumeComments(volumeId);render()}catch(e){toast(friendlyError(e),'bad')}}
async function loadReaderComments(sectionId){const rows=await jreq(`/rest/v1/comments?section_id=eq.${sectionId}&select=id,section_id,user_id,parent_id,body,is_spoiler,created_at,profiles(id,username,display_name),comment_reactions(user_id,reaction)&order=created_at.asc`);S.readerComments=(rows||[]).map(c=>({...c,like_count:(c.comment_reactions||[]).filter(r=>r.reaction==='like').length,liked_by_me:!!S.user&&(c.comment_reactions||[]).some(r=>r.user_id===S.user.id&&r.reaction==='like')}))}
async function postComment(parentId=null,bodyOverride=null){try{if(!S.user||!S.volumeCommentSectionId)return;const body=(bodyOverride ?? $('#newCommentBody')?.value?.trim() ?? '');if(body.length<1){toast('Escribe un comentario.','bad');return}const is_spoiler=parentId?false:!!$('#newCommentSpoiler')?.checked;await jreq('/rest/v1/comments',{method:'POST',headers:{Prefer:'return=minimal'},body:JSON.stringify({section_id:S.volumeCommentSectionId,user_id:S.user.id,parent_id:parentId,body,is_spoiler})});await loadVolumeComments(S.volumeCommentsId);render();toast('Comentario publicado.','ok')}catch(e){toast(friendlyError(e),'bad')}}
async function replyComment(id){const body=prompt('Escribe tu respuesta:');if(body&&body.trim())await postComment(id,body.trim())}
async function toggleCommentLike(id){try{if(!S.user){go('auth');return}const c=S.readerComments.find(x=>x.id===id);if(c?.liked_by_me){await jreq(`/rest/v1/comment_reactions?comment_id=eq.${id}&user_id=eq.${S.user.id}&reaction=eq.like`,{method:'DELETE',headers:{Prefer:'return=minimal'}})}else{await jreq('/rest/v1/comment_reactions',{method:'POST',headers:{Prefer:'return=minimal'},body:JSON.stringify({comment_id:id,user_id:S.user.id,reaction:'like'})})}await loadVolumeComments(S.volumeCommentsId);render()}catch(e){toast(friendlyError(e),'bad')}}
async function reportComment(id){if(!S.user){go('auth');return}const reason=prompt('Motivo del reporte:');if(!reason?.trim())return;try{await jreq('/rest/v1/comment_reports',{method:'POST',headers:{Prefer:'return=minimal'},body:JSON.stringify({comment_id:id,reporter_id:S.user.id,reason:reason.trim(),status:'pending'})});toast('Reporte enviado.','ok')}catch(e){toast(friendlyError(e),'bad')}}
function detailFallbackRoute(){const r=S.detailBackRoute;return r&&validRoute(r)&&!r.startsWith('detail:')&&!r.startsWith('reader:')?r:'explore'}
function goBackFromDetail(){go(detailFallbackRoute())}
async function openDetail(id){if(S.detailVolumeTranslationId!==id){S.detailVolumeId=null;S.volumeCommentsId=null}S.detailVolumeTranslationId=id;if(!S.view.startsWith('detail:')&&!S.view.startsWith('reader:'))S.detailBackRoute=S.view;try{S.currentDetail=await loadTranslationDetail(id);go('detail:'+id)}catch(e){toast(friendlyError(e),'bad')}}
async function loadTranslationDetail(id){const rows=await jreq(`/rest/v1/translations?id=eq.${id}&select=id,title,status,language_code,popularity_score,updated_at,novels(id,title,synopsis,cover_url,author_name,genres,tags,demography),translator_groups(id,name,review_required),volumes(id,volume_number,title,status,cover_url,sections(id,title,section_type,section_number,status,sort_order),download_links(id,format,provider,url))&limit=1`);const x=rows?.[0]||null;if(!x||!['active','complete','paused'].includes(x.status))return null;const publicVolumeIds=new Set((x.volumes||[]).filter(v=>v.status==='published').map(v=>v.id));const [purchase,support,downloads]=await Promise.all([jreq(`/rest/v1/purchase_links?novel_id=eq.${x.novels?.id}&is_verified=eq.true&select=id,volume_number,store_name,region,language_code,format,url&order=volume_number.asc`),x.translator_groups?.id?jreq(`/rest/v1/support_links?group_id=eq.${x.translator_groups.id}&select=id,label,url&order=created_at.asc`):Promise.resolve([]),publicVolumeIds.size?jreq(`/rest/v1/download_links?volume_id=in.(${[...publicVolumeIds].join(',')})&select=id,volume_id,format,provider,url&order=created_at.asc`):Promise.resolve([])]);x.links={purchase:purchase||[],support:support||[],downloads:(downloads||[]).filter(l=>publicVolumeIds.has(l.volume_id))};return x}

async function uploadPersonalBanner(e){try{const file=e.target.files?.[0];if(!file||!S.user)return;const url=await storageUpload(file,`users/${S.user.id}/banner/${mediaStableName('banner',file)}`,true);const input=$('#profileBannerUrl');if(input)input.value=url;const preview=$('#readerBannerPreview');if(preview)preview.style.backgroundImage='url("'+safeCssUrl(url)+'")';toast('Banner subido. Guarda el perfil para aplicarlo.','ok')}catch(error){toast(friendlyError(error),'bad')}}
async function uploadPersonalAvatar(e){try{const file=e.target.files?.[0];if(!file||!S.user)return;const url=await storageUpload(file,`users/${S.user.id}/avatar/${mediaStableName('avatar',file)}`,true);const input=$('#profileAvatarUrl');if(input)input.value=url;toast('Avatar subido. Guarda el perfil para aplicarlo.','ok')}catch(err){toast(friendlyError(err),'bad')}}
async function changePersonalPassword(event){event.preventDefault();if(!S.user||!S.token)return;const form=event.currentTarget,button=$('#readerChangePassword'),message=$('#readerPasswordMessage'),current=$('#readerCurrentPassword')?.value||'',next=$('#readerNewPassword')?.value||'',confirmation=$('#readerConfirmPassword')?.value||'';const inform=(value,error=false)=>{if(message){message.hidden=false;message.textContent=value;message.style.color=error?'var(--danger,#b42318)':'var(--muted)'}};if(next.length<12||next.length>128){inform('La nueva contraseña debe tener entre 12 y 128 caracteres.',true);return}if(next!==confirmation){inform('Las nuevas contraseñas no coinciden.',true);return}if(current===next){inform('La nueva contraseña debe ser distinta a la actual.',true);return}if(!current){inform('Escribe tu contraseña actual.',true);return}if(button)button.disabled=true;try{if(!S.user.email){inform('Tu cuenta no tiene un correo de acceso por contraseña.',true);return}await jreq('/auth/v1/token?grant_type=password',{method:'POST',body:JSON.stringify({email:S.user.email,password:current})});await jreq('/auth/v1/user',{method:'PUT',body:JSON.stringify({password:next,current_password:current})});form.reset();inform('Contraseña actualizada correctamente.');toast('Tu contraseña se actualizó.','ok')}catch(error){const raw=String(error?.message||'');let txt='No se pudo actualizar la contraseña. Comprueba tu contraseña actual e inténtalo de nuevo.';if(/reauth|nonce/i.test(raw))txt='Supabase solicita una verificación adicional para cambiar la contraseña. Revisa los ajustes de reautenticación de Auth.';inform(txt,true);toast(txt,'bad')}finally{if(button)button.disabled=false}}
async function savePersonalProfile(){try{if(!S.user)return;const oldAvatar=S.profile?.avatar_url||null,oldBanner=S.profile?.banner_url||null,username=$('#profileUsername')?.value.trim().replace(/^@/,'')||null;if(username&&(!/^[A-Za-z0-9_.-]{3,40}$/.test(username))){toast('El nombre de usuario debe tener 3-40 caracteres y usar letras, números, punto, guion o guion bajo.','bad');return}const body={display_name:$('#profileDisplayName')?.value.trim()||null,username,avatar_url:$('#profileAvatarUrl')?.value.trim()||null,banner_url:$('#profileBannerUrl')?.value.trim()||null,bio:$('#profileBio')?.value.trim()||null,public_library:!!$('#profilePublicLibrary')?.checked,public_activity:!!$('#profilePublicActivity')?.checked,updated_at:new Date().toISOString()};await jreq(`/rest/v1/profiles?id=eq.${S.user.id}`,{method:'PATCH',headers:{Prefer:'return=minimal'},body:JSON.stringify(body)});await loadUser();if(oldAvatar&&oldAvatar!==body.avatar_url)await deleteOldMediaIfUnused(oldAvatar);if(oldBanner&&oldBanner!==body.banner_url)await deleteOldMediaIfUnused(oldBanner);render();toast('Perfil actualizado.','ok')}catch(e){const m=String(e?.message||'');toast(/duplicate|23505/i.test(m)?'Ese nombre de usuario ya está en uso.':friendlyError(e),'bad')}}
async function openPublicProfile(id){try{S.publicProfile=await loadPublicProfileData(id);go('profile:'+id)}catch(e){toast(friendlyError(e),'bad')}}
async function openGroup(id){try{S.publicGroup=await loadPublicGroupData(id);go('group:'+id)}catch(e){toast(friendlyError(e),'bad')}}

function roleLabel(role){return({owner:'Owner',admin:'Admin',translator:'Traductor',editor:'Editor',proofreader:'Corrector',collaborator:'Colaborador'}[role]||role||'Miembro')}
const TEAM_PERMISSION_ACTIONS=[['edit','Editar contenido'],['create','Crear obras y volúmenes'],['import','Importar archivos'],['publish','Publicar y ocultar'],['schedule','Programar publicaciones'],['delete','Eliminar contenido'],['review','Revisar y aprobar']];
function defaultTeamPermission(role,action){
 if(['owner','admin'].includes(role))return true;
 if(['edit','create','import','publish','schedule'].includes(action))return ['translator','editor'].includes(role);
 if(action==='delete')return role==='translator';
 if(action==='review')return ['translator','editor','proofreader'].includes(role);
 return false;
}
function teamCan(groupId,action){
 if(S.admin)return true;const gm=S.groups.find(g=>g.translator_groups?.id===groupId);if(!gm)return false;
 if(['owner','admin'].includes(gm.role))return true;
 if(typeof gm.permissions?.[action]==='boolean')return gm.permissions[action];
 return defaultTeamPermission(gm.role,action);
}
function teamPermissionEditor(G){
 if(!isCurrentGroupManager(G.id))return '';
 return `<section class="teamPermissionsPanel" id="teamRoles"><div class="sectionHead"><div><h2>Roles y permisos</h2><p>Personaliza el acceso de cada miembro sin cambiar su función en el equipo. «Heredado» aplica el permiso predeterminado del rol.</p></div></div>${S.teamMembers.every(m=>m.role==='owner')?'<div class="notice">Actualmente solo está registrado el propietario del equipo. Agrega otro miembro desde «Miembros y roles» para configurar sus permisos individuales.</div>':''}<div class="teamPermissionsGrid">${S.teamMembers.map(m=>`<article class="teamPermissionCard"><header><strong>${esc(m.profiles?.display_name||m.profiles?.username||'Miembro')}</strong><span class="badge">${esc(roleLabel(m.role))}</span></header>${['owner','admin'].includes(m.role)?'<p class="muted">Rol administrativo: acceso completo y protegido. Cambia primero el rol si deseas limitarlo.</p>':`<div class="teamPermissionControls">${TEAM_PERMISSION_ACTIONS.map(([key,label])=>{const value=m.permissions?.[key];return `<label><span>${esc(label)}</span><select data-team-permission="${key}" data-permission-member="${m.user_id}" aria-label="${esc(label)} para ${esc(m.profiles?.username||'miembro')}"><option value="inherit" ${typeof value!=='boolean'?'selected':''}>Heredado (${defaultTeamPermission(m.role,key)?'Sí':'No'})</option><option value="allow" ${value===true?'selected':''}>Permitir</option><option value="deny" ${value===false?'selected':''}>Denegar</option></select></label>`}).join('')}</div><button class="btn primary" data-save-team-permissions="${m.user_id}">Guardar permisos</button>`}</article>`).join('')}</div></section>`
}
async function saveTeamMemberPermissions(userId){
 const G=S.studioTeam;if(!G||!isCurrentGroupManager(G.id))return;
 const m=S.teamMembers.find(x=>x.user_id===userId);if(!m||['owner','admin'].includes(m.role))return;
 const permissions={};Array.from(document.querySelectorAll('[data-permission-member]')).filter(el=>el.dataset.permissionMember===userId).forEach(el=>{if(el.value!=='inherit')permissions[el.dataset.teamPermission]=el.value==='allow'});
 try{await jreq('/rest/v1/group_members?group_id=eq.'+G.id+'&user_id=eq.'+userId,{method:'PATCH',headers:{Prefer:'return=minimal'},body:JSON.stringify({permissions})});await loadTeamMembers(G.id);await loadUser();render();toast('Permisos actualizados.','ok')}
 catch(e){toast(friendlyError(e,'No se pudieron guardar los permisos.'),'bad')}
}
function myGroupRole(groupId){return S.groups.find(g=>g.translator_groups?.id===groupId)?.role||null}
function isCurrentGroupEditor(groupId){return S.admin||['edit','create','import','publish','schedule','delete'].some(a=>teamCan(groupId,a))}
function isCurrentGroupManager(groupId){return ['owner','admin'].includes(myGroupRole(groupId))||S.admin}
function editorialGroups(){return S.groups.filter(g=>isCurrentGroupEditor(g.translator_groups?.id))}
async function loadTeamMembers(groupId){S.teamMembers=await jreq(`/rest/v1/group_members?group_id=eq.${groupId}&select=group_id,user_id,role,permissions,profiles(id,username,display_name,avatar_url)&order=role.asc`)||[]}
async function resolveProfileByUsername(value){const raw=String(value||'').trim().replace(/^@/,'');if(!raw)return null;let rows=await jreq(`/rest/v1/profiles?username=eq.${encodeURIComponent(raw)}&select=id,username,display_name&limit=1`);if(rows?.[0])return rows[0];if(/^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i.test(raw)){rows=await jreq(`/rest/v1/profiles?id=eq.${raw}&select=id,username,display_name&limit=1`);return rows?.[0]||null}return null}
async function addTeamMember(){try{const G=S.studioTeam;if(!G||!isCurrentGroupManager(G.id)){toast('No tienes permiso para administrar miembros.','bad');return}const mode=$('#memberLookupMode')?.value||'username',lookup=$('#memberUsername')?.value.trim()||'';if(!lookup){toast('Ingresa un nombre de usuario o correo electrónico.','bad');return}const profile=mode==='email'?(await jreq('/rest/v1/rpc/find_team_member_by_email',{method:'POST',body:JSON.stringify({p_group_id:G.id,p_email:lookup})}))?.[0]:await resolveProfileByUsername(lookup);if(!profile){toast('No encontramos una cuenta registrada con esos datos.','bad');return}const role=$('#memberRole')?.value||'translator';if(role==='owner'){toast('El owner no se asigna desde aquí.','bad');return}await jreq('/rest/v1/group_members',{method:'POST',headers:{Prefer:'return=minimal'},body:JSON.stringify({group_id:G.id,user_id:profile.id,role})});await loadTeamMembers(G.id);await loadStudioData();render();toast(`${profile.display_name||profile.username||'Usuario'} fue agregado al equipo.`,'ok')}catch(e){const m=String(e?.message||'');toast(/duplicate|23505/i.test(m)?'Ese usuario ya pertenece al equipo.':friendlyError(e),'bad')}}
async function changeTeamMemberRole(userId,role){try{const G=S.studioTeam;if(!G||!isCurrentGroupManager(G.id)||!['admin','translator','editor','proofreader','collaborator'].includes(role))return;if(userId===S.user?.id){toast('No puedes modificar tu propio rol desde esta sesión.','bad');return}const m=S.teamMembers.find(x=>x.user_id===userId);if(!m||m.role==='owner')return;await jreq(`/rest/v1/group_members?group_id=eq.${G.id}&user_id=eq.${userId}`,{method:'PATCH',headers:{Prefer:'return=minimal'},body:JSON.stringify({role})});await loadTeamMembers(G.id);await loadStudioData();render();toast('Rol actualizado.','ok')}catch(e){toast(friendlyError(e),'bad')}}
async function removeTeamMember(userId){try{const G=S.studioTeam;if(!G||!isCurrentGroupManager(G.id))return;if(userId===S.user?.id){toast('No puedes retirarte a ti mismo desde esta sección.','bad');return}const m=S.teamMembers.find(x=>x.user_id===userId);if(!m||m.role==='owner'){toast('El owner del equipo está protegido.','bad');return}await jreq(`/rest/v1/group_members?group_id=eq.${G.id}&user_id=eq.${userId}`,{method:'DELETE',headers:{Prefer:'return=minimal'}});await loadTeamMembers(G.id);await loadStudioData();render();toast('Acceso retirado.','ok')}catch(e){toast(friendlyError(e),'bad')}}

async function openMediaLibrary(groupId,target=null){try{if(!groupId)throw new Error('No se pudo determinar el equipo.');if(!isCurrentGroupEditor(groupId))throw new Error('Tu rol no puede gestionar la biblioteca multimedia.');S.mediaGroupId=groupId;S.mediaTarget=target;S.mediaQuery='';S.mediaPage=0;S.mediaUsage={};S.mediaSelected=[];S.mediaFolderNovel='all';S.mediaFolderVolume='all';S.mediaFolderIndex=[];S.mediaLoading=true;go('studio:media:'+groupId);render();S.mediaFiles=await storageWalk(`teams/${groupId}`);await Promise.all([loadMediaUsage(S.mediaFiles.map(x=>x.path)),loadMediaFolders(groupId)]);S.mediaLoading=false;render()}catch(e){S.mediaLoading=false;toast(friendlyError(e),'bad')}}
function mediaBack(){const gid=S.mediaGroupId,target=S.mediaTarget;S.mediaTarget=null;if(target&&S.studioProject?.group_id===gid)go('studio:project:'+S.studioProject.id);else if(S.studioTeam?.id===gid)go('studio:team:'+gid);else go('studio')}
async function uploadMediaLibraryFile(file){try{if(!file||!S.mediaGroupId)return;const folder=(S.mediaFolderIndex||[]).find(x=>x.novel===S.mediaFolderNovel&&x.volume===S.mediaFolderVolume);const destination=folder?.volumeId?'volume-'+folder.volumeId:folder?.novelId?'novel-'+folder.novelId:'general';const path=`teams/${S.mediaGroupId}/library/${destination}/${storageName('media',file)}`;await storageUpload(file,path,false);S.mediaFiles=await storageWalk(`teams/${S.mediaGroupId}`);await Promise.all([loadMediaUsage(S.mediaFiles.map(x=>x.path)),loadMediaFolders(S.mediaGroupId)]);S.mediaPage=0;render();toast('Imagen añadida a la biblioteca.','ok')}catch(e){toast(friendlyError(e),'bad')}}
async function useMediaAsset(path){try{const url=storagePublicUrl(path),t=S.mediaTarget;if(!t){await copyMediaUrl(path);return}if(t==='team-avatar'){await jreq(`/rest/v1/translator_groups?id=eq.${S.mediaGroupId}`,{method:'PATCH',headers:{Prefer:'return=minimal'},body:JSON.stringify({avatar_url:url,updated_at:new Date().toISOString()})});S.studioTeam=await loadStudioTeam(S.mediaGroupId);S.mediaTarget=null;go('studio:team:'+S.mediaGroupId);toast('Avatar actualizado.','ok');return}if(t==='team-banner'){await jreq(`/rest/v1/translator_groups?id=eq.${S.mediaGroupId}`,{method:'PATCH',headers:{Prefer:'return=minimal'},body:JSON.stringify({banner_url:url,updated_at:new Date().toISOString()})});S.studioTeam=await loadStudioTeam(S.mediaGroupId);S.mediaTarget=null;go('studio:team:'+S.mediaGroupId);toast('Banner actualizado.','ok');return}if(t==='novel-cover'){if(!S.studioProject?.novels?.id)throw new Error('No hay proyecto activo.');await jreq(`/rest/v1/novels?id=eq.${S.studioProject.novels.id}`,{method:'PATCH',headers:{Prefer:'return=minimal'},body:JSON.stringify({cover_url:url,updated_at:new Date().toISOString()})});S.mediaTarget=null;await refreshStudioProject();go('studio:project:'+S.studioProject.id);toast('Portada actualizada.','ok');return}if(t.startsWith('volume-cover:')){const id=t.split(':')[1];await jreq(`/rest/v1/volumes?id=eq.${id}`,{method:'PATCH',headers:{Prefer:'return=minimal'},body:JSON.stringify({cover_url:url,updated_at:new Date().toISOString()})});S.mediaTarget=null;await refreshStudioProject();go('studio:project:'+S.studioProject.id);toast('Portada del volumen actualizada.','ok');return}if(t.startsWith('block:')){const i=Number(t.split(':')[1]);if(!S.blockEditor?.blocks?.[i])throw new Error('El bloque ya no está disponible.');S.blockEditor.blocks[i].url=url;S.mediaTarget=null;go('studio:project:'+S.studioProject.id);toast('Ilustración seleccionada.','ok');return}}catch(e){toast(friendlyError(e),'bad')}}
async function copyMediaUrl(path){try{const url=storagePublicUrl(path);if(navigator.clipboard?.writeText)await navigator.clipboard.writeText(url);else{const ta=document.createElement('textarea');ta.value=url;document.body.appendChild(ta);ta.select();document.execCommand('copy');ta.remove()}toast('URL copiada.','ok')}catch(e){toast('No se pudo copiar la URL.','bad')}}
async function mediaBulkDelete(paths,label){
 const list=[...new Set(paths)].filter(path=>S.mediaFiles.some(x=>x.path===path));
 if(!list.length){toast('No hay imágenes para borrar.','bad');return}
 if(!confirm('¿Eliminar '+list.length+' imágenes de '+label+'? Solo se borrarán archivos sin referencias activas.'))return;
 try{
  await loadMediaUsage(S.mediaFiles.map(x=>x.path));
  const safe=list.filter(path=>Number(S.mediaUsage?.[path]||0)===0),blocked=list.length-safe.length;
  let removed=0,failed=0,firstError='';
  for(const path of safe){try{await storageDelete(path);removed++}catch(e){failed++;if(!firstError)firstError=friendlyError(e,'No se pudo eliminar')}}
  S.mediaFiles=await storageWalk('teams/'+S.mediaGroupId);
  await Promise.all([loadMediaUsage(S.mediaFiles.map(x=>x.path)),loadMediaFolders(S.mediaGroupId)]);
  S.mediaSelected=[];S.mediaPage=0;render();
  toast(removed+' eliminadas; '+blocked+' protegidas por uso; '+failed+' errores.'+(firstError?' '+firstError:''),failed||(!removed&&blocked)?'bad':'ok')
 }catch(e){toast(friendlyError(e),'bad')}
}
async function deleteMediaAsset(path){try{if(!path)return;if(S.mediaUsage?.[path]===undefined)await loadMediaUsage([path]);if(Number(S.mediaUsage?.[path]||0)>0){toast('No puedes eliminar esta imagen porque todavía está siendo usada.','bad');return}if(!confirm('¿Eliminar definitivamente esta imagen?'))return;await loadMediaUsage([path]);if(Number(S.mediaUsage?.[path]||0)>0){toast('Esta imagen sigue en uso.','bad');return}await storageDelete(path);S.mediaSelected=(S.mediaSelected||[]).filter(x=>x!==path);S.mediaFiles=S.mediaFiles.filter(x=>x.path!==path);delete S.mediaUsage[path];render();toast('Archivo eliminado de Storage.','ok')}catch(e){toast(friendlyError(e),'bad')}}
async function cleanupOrphanMedia(){try{await loadMediaUsage(S.mediaFiles.map(x=>x.path));const orphan=S.mediaFiles.filter(x=>Number(S.mediaUsage?.[x.path]||0)===0);if(!orphan.length){toast('No hay archivos huérfanos.','ok');return}if(!confirm(`Se eliminarán ${orphan.length} archivo(s) sin referencias. ¿Continuar?`))return;let removed=0,failed=0;for(const f of orphan){try{await storageDelete(f.path);removed++;delete S.mediaUsage[f.path]}catch{failed++}}S.mediaFiles=await storageWalk(`teams/${S.mediaGroupId}`);await loadMediaUsage(S.mediaFiles.map(x=>x.path));S.mediaPage=0;render();toast(failed?`${removed} eliminados; ${failed} no pudieron borrarse.`:`${removed} archivos huérfanos eliminados.`,failed?'bad':'ok')}catch(e){toast(friendlyError(e),'bad')}}async function storageSelfTest(){try{if(!S.mediaGroupId)throw new Error('Abre primero una biblioteca de equipo.');const prefix=`teams/${S.mediaGroupId}/_tests`,name=`storage-e2e-${Date.now().toString(36)}.png`,path=`${prefix}/${name}`,a=await testPngFile(1,name),b=await testPngFile(5,name);await storageUpload(a,path,false);let rows=await storageListFolder(prefix,0,200),first=rows.find(x=>x.name===name);if(!first)throw new Error('INSERT no apareció en el listado.');const firstSize=Number(first.metadata?.size||0);await storageUpload(b,path,true);rows=await storageListFolder(prefix,0,200);const second=rows.find(x=>x.name===name);if(!second)throw new Error('UPDATE/upsert eliminó el objeto inesperadamente.');const secondSize=Number(second.metadata?.size||0);if(firstSize===secondSize)console.warn('El tamaño del archivo de prueba no cambió; el upsert sí respondió correctamente.');await storageDelete(path);rows=await storageListFolder(prefix,0,200);if(rows.some(x=>x.name===name))throw new Error('DELETE no eliminó el objeto de prueba.');toast('Storage E2E correcto: subir, reemplazar, listar y borrar.','ok')}catch(e){toast('Prueba Storage: '+friendlyError(e),'bad')}}

async function openStudioTeam(id){if(!id)return;try{S.teamSettingsTab='identity';S.studioTeam=await loadStudioTeam(id);if(!S.studioTeam)throw new Error('No se pudo encontrar el equipo.');await loadTeamMembers(id);go('studio:team:'+id)}catch(e){toast(friendlyError(e,'No se pudo abrir la gestión del equipo.'),'bad')}}
