async function saveStudioTeamProfile(){try{const G=S.studioTeam;if(!G)return;const primary=$('#teamEditPrimary')?.value.trim()||null,secondary=$('#teamEditSecondary')?.value.trim()||null;if([primary,secondary].some(color=>color&&!/^#[0-9a-fA-F]{6}$/.test(color))){toast('Introduce colores válidos en formato #RRGGBB.','bad');return}const oldAvatar=G.avatar_url||null,oldBanner=G.banner_url||null,body={name:$('#teamEditName')?.value.trim()||G.name,description:$('#teamEditDescription')?.value.trim()||null,avatar_url:$('#teamEditAvatar')?.value.trim()||null,banner_url:$('#teamEditBanner')?.value.trim()||null,primary_color:primary,secondary_color:secondary,updated_at:new Date().toISOString()};await jreq(`/rest/v1/translator_groups?id=eq.${G.id}`,{method:'PATCH',headers:{Prefer:'return=minimal'},body:JSON.stringify(body)});await refreshStudioTeam();if(oldAvatar&&oldAvatar!==body.avatar_url)await deleteOldMediaIfUnused(oldAvatar);if(oldBanner&&oldBanner!==body.banner_url)await deleteOldMediaIfUnused(oldBanner);toast('Perfil del equipo actualizado.','ok')}catch(e){toast(friendlyError(e),'bad')}}
async function addSupportLink(){try{const G=S.studioTeam,label=$('#supportLabel')?.value.trim(),url=$('#supportUrl')?.value.trim();if(!G||!label||!url){toast('Completa etiqueta y URL.','bad');return}if(!/^https:\/\//i.test(url)||safeUrl(url)==='#'){toast('Introduce un enlace HTTPS válido.','bad');return}await jreq('/rest/v1/support_links',{method:'POST',headers:{Prefer:'return=minimal'},body:JSON.stringify({group_id:G.id,label,url:safeUrl(url)})});await refreshStudioTeam();toast('Enlace de apoyo agregado.','ok')}catch(e){toast(friendlyError(e),'bad')}}
