async function openStudioProject(id){try{S.studioProject=await loadStudioProject(id);go('studio:project:'+id)}catch(e){toast(friendlyError(e),'bad')}}
async function loadStudioProject(id){const rows=await jreq(`/rest/v1/translations?id=eq.${id}&select=id,title,status,language_code,group_id,novels(id,title,synopsis,cover_url,author_name,genres,tags,demography),translator_groups(id,name),volumes(id,volume_number,title,status,cover_url,sections(id,title,section_type,section_number,status,sort_order,content,updated_at))&limit=1`);const p=rows?.[0]||null;if(!p)return null;const volumeIds=(p.volumes||[]).map(v=>v.id);const sectionIds=(p.volumes||[]).flatMap(v=>(v.sections||[]).map(sec=>sec.id));const [purchase,downloads,schedules,reviews,reviewMembers]=await Promise.all([jreq(`/rest/v1/purchase_links?novel_id=eq.${p.novels?.id}&group_id=eq.${p.group_id}&select=id,volume_number,store_name,region,language_code,format,url,is_verified&order=created_at.asc`),volumeIds.length?jreq(`/rest/v1/download_links?volume_id=in.(${volumeIds.join(',')})&select=id,volume_id,format,provider,url&order=created_at.asc`):Promise.resolve([]),volumeIds.length?jreq(`/rest/v1/volume_publication_schedule?volume_id=in.(${volumeIds.join(',')})&status=in.(pending,failed)&select=id,volume_id,scheduled_at,status,error_message&order=scheduled_at.asc`):Promise.resolve([]),sectionIds.length?jreq(`/rest/v1/editorial_review_requests?section_id=in.(${sectionIds.join(',')})&select=id,section_id,group_id,requested_by,assigned_to,status,request_note,review_note,reviewed_by,created_at,reviewed_at&order=created_at.desc&limit=500`):Promise.resolve([]),jreq(`/rest/v1/group_members?group_id=eq.${p.group_id}&select=user_id,role,permissions,profiles(id,username,display_name)`)]);p.purchase_links=purchase||[];p.download_links=downloads||[];p.publication_schedules=schedules||[];p.review_requests=reviews||[];p.review_members=reviewMembers||[];return p}
async function refreshStudioProject(){if(!S.studioProject?.id)return;S.studioProject=await loadStudioProject(S.studioProject.id);render()}

const NOVEL_GENRES=["Acción","Aventura","Artes marciales","Ciencia ficción","Comedia","Crimen","Deportes","Drama","Ecchi","Escolar","Fantasía","Fantasía oscura","Harem","Histórico","Horror","Isekai","Josei","Maduro","Mecha","Misterio","Música","Psicológico","Recuentos de la vida","Reencarnación","Romance","Seinen","Shōjo","Shōnen","Sobrenatural","Supervivencia","Suspenso","Terror","Tragedia","Videojuegos","Villana","Yuri","Yaoi"];
const NOVEL_DEMOGRAPHICS=['Shōnen','Shōjo','Seinen','Josei','Kodomo','General'];
function novelGenresPicker(id,selected=[]){const catalogGenres=(S.catalog||[]).flatMap(x=>x.novels?.genres||x.genres||[]);const choices=[...new Set([...NOVEL_GENRES,...catalogGenres,...selected])].sort((a,b)=>a.localeCompare(b,'es'));return `<details id="${id}" class="genreDropdown"><summary>Seleccionar géneros <span class="muted">(puedes elegir varios)</span></summary><div class="genreDropdownOptions" role="group" aria-label="Géneros disponibles">${choices.map(g=>`<label><input type="checkbox" name="${id}-choice" value="${esc(g)}" ${selected.includes(g)?'checked':''}> ${esc(g)}</label>`).join('')}</div></details>`}
function selectedNovelGenres(id){return [...document.querySelectorAll('input[name="'+id+'-choice"]:checked')].map(o=>o.value)}
function novelDemographyPicker(id,current=''){return `<select id="${id}" required><option value="">Seleccionar demografía</option>${NOVEL_DEMOGRAPHICS.map(d=>`<option value="${esc(d)}" ${d===current?'selected':''}>${esc(d)}</option>`).join('')}</select>`}
function splitMetaList(v){return [...new Set(String(v||'').split(',').map(x=>x.trim()).filter(Boolean).slice(0,30))]}
