function slugify(v){return String(v||'').normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase().replace(/[^a-z0-9]+/g,'-').replace(/^-|-$/g,'').slice(0,90)||'obra'}
async function createStudioProject(){let uploadedCoverPath=null;try{const group_id=$('#newGroup')?.value,title=$('#newNovelTitle')?.value.trim(),title_original=$('#newNovelOriginal')?.value.trim()||null,author_name=$('#newNovelAuthor')?.value.trim()||null,synopsis=$('#newNovelSynopsis')?.value.trim()||null,genres=selectedNovelGenres('newNovelGenres'),demography=$('#newNovelDemography')?.value,tags=splitMetaList($('#newNovelTags')?.value),language_code=$('#newTranslationLanguage')?.value.trim()||'es';let cover_url=$('#newNovelCover')?.value.trim()||null;const coverFile=$('#newNovelCoverFile')?.files?.[0];if(!group_id||!title||!genres.length||!demography){toast('Completa el equipo, título, géneros y demografía.','bad');return}if(!isCurrentGroupEditor(group_id)){toast('Tu rol no puede crear proyectos en ese equipo.','bad');return}if(coverFile){uploadedCoverPath=`teams/${group_id}/covers/${storageName('cover',coverFile)}`;cover_url=await storageUpload(coverFile,uploadedCoverPath,false)}const rows=await jreq('/rest/v1/rpc/create_translation_project',{method:'POST',body:JSON.stringify({p_group_id:group_id,p_title:title,p_title_original:title_original,p_author_name:author_name,p_synopsis:synopsis,p_cover_url:cover_url,p_genres:genres,p_tags:tags,p_language_code:language_code})});const t=rows?.[0];if(!t?.translation_id)throw new Error('No se pudo crear el proyecto.');await jreq('/rest/v1/novels?id=eq.'+t.novel_id,{method:'PATCH',headers:{Prefer:'return=minimal'},body:JSON.stringify({demography})});await loadStudioData();S.studioProject=await loadStudioProject(t.translation_id);go('studio:project:'+t.translation_id);toast('Proyecto creado.','ok')}catch(e){if(uploadedCoverPath)try{await storageDelete(uploadedCoverPath)}catch{}toast(friendlyError(e),'bad')}}
async function saveVolumeMeta(){const id=S.studioEditVolumeId;if(!id)return;try{const title=$('#editVolumeTitle')?.value.trim()||null,cover_url=$('#editVolumeCoverUrl')?.value.trim()||null,volume_number=Number($('#editVolumeNumber')?.value);if(!Number.isFinite(volume_number)||volume_number<0){toast('Indica un número de volumen válido.','bad');return}if((S.studioProject?.volumes||[]).some(v=>v.id!==id&&Number(v.volume_number)===volume_number)){toast('Ya existe otro volumen con ese número.','bad');return}if(cover_url&&!/^https:\/\//i.test(cover_url)){toast('La portada debe utilizar una URL HTTPS.','bad');return}await jreq('/rest/v1/volumes?id=eq.'+id,{method:'PATCH',headers:{Prefer:'return=minimal'},body:JSON.stringify({title,cover_url,volume_number,updated_at:new Date().toISOString()})});await refreshStudioProject();toast('Volumen actualizado.','ok')}catch(e){toast(friendlyError(e),'bad')}}
