async function deleteStudioVolume(id){try{if(!teamCan(S.studioProject?.group_id,'delete')){toast('No tienes permiso para eliminar volúmenes.','bad');return}const P=S.studioProject,vol=P?.volumes?.find(x=>x.id===id);if(!P||!vol)return;const count=(vol.sections||[]).length,label=`Vol. ${vol.volume_number}${vol.title?' · '+vol.title:''}`;if(!confirm(`¿Eliminar "${label}" definitivamente? También se borrarán sus ${count} capítulo${count===1?'':'s'}, revisiones, comentarios, descargas, enlaces oficiales de ese volumen y archivos multimedia que ya no estén en uso.`))return;const sectionIds=(vol.sections||[]).map(sec=>sec.id),media=[vol.cover_url,...(vol.sections||[]).flatMap(sectionMediaUrls),...await revisionMediaUrls(sectionIds)].filter(Boolean);if(P.novels?.id&&P.group_id)await jreq(`/rest/v1/purchase_links?novel_id=eq.${P.novels.id}&group_id=eq.${P.group_id}&volume_number=eq.${encodeURIComponent(vol.volume_number)}`,{method:'DELETE',headers:{Prefer:'return=minimal'}});await jreq(`/rest/v1/volumes?id=eq.${id}`,{method:'DELETE',headers:{Prefer:'return=minimal'}});if((vol.sections||[]).some(sec=>sec.id===S.studioProject?.editingSection?.id)){S.studioProject.editingSection=null;S.blockEditor=null;S.revisionHistory=[];S.revisionPreview=null}await cleanupDeletedMedia(media);await refreshStudioProject();await loadCatalog();toast(`Volumen y ${count} capítulo${count===1?'':'s'} eliminados definitivamente.`,'ok')}catch(e){toast(friendlyError(e),'bad')}}

