async function loadBetaFeedback(){if(!S.user){S.betaFeedback=[];S.betaFeedbackError='';return}S.betaFeedbackError='';try{S.betaFeedback=await jreq(`/rest/v1/beta_feedback?user_id=eq.${encodeURIComponent(S.user.id)}&select=id,category,title,description,status,priority,admin_note,created_at,updated_at&order=created_at.desc&limit=50`)||[]}catch(e){S.betaFeedbackError=friendlyError(e);throw e}}
async function runBetaChecks(){if(S.betaRunning)return;S.betaRunning=true;S.betaChecks=[];render();const tests=[];const run=async(label,fn)=>{try{const detail=await fn();tests.push({label,ok:true,detail:detail||'Correcto'})}catch(e){tests.push({label,ok:false,detail:friendlyError(e)})}S.betaChecks=tests.slice();render()};try{await run('Frontend',async()=>`Vista ${S.view} renderizada`);await run('Supabase Data API',async()=>{await jreq('/rest/v1/translations?select=id&limit=1');return'Consulta pública correcta'});await run('Sesión Auth',async()=>{const u=await jreq('/auth/v1/user');if(!u?.id)throw Error('Sesión no válida');return'Sesión válida'});await run('Perfil',async()=>{const p=await jreq(`/rest/v1/profiles?id=eq.${S.user.id}&select=id&limit=1`);if(!p?.length)throw Error('Perfil no encontrado');return'Perfil accesible'});await run('Biblioteca',async()=>{await jreq(`/rest/v1/library_entries?user_id=eq.${S.user.id}&select=translation_id&limit=1`);return'Consulta de biblioteca completada'});await run('Studio / equipos',async()=>{await jreq(`/rest/v1/group_members?user_id=eq.${S.user.id}&select=group_id&limit=1`);return'Consulta de equipos completada'})}finally{S.betaRunning=false;S.betaChecks=tests;render();toast(tests.every(x=>x.ok)?'Diagnóstico completado sin fallos.':'Diagnóstico completado con incidencias.',tests.every(x=>x.ok)?'ok':'bad')}}
async function submitBetaFeedback(){if(S.betaSubmitting)return;const category=$('#betaCategory')?.value||'bug',title=$('#betaTitle')?.value.trim()||'',description=$('#betaDescription')?.value.trim()||'';if(!S.user){toast('Inicia sesión para enviar reportes.','bad');return}if(!['bug','ux','content','performance','other'].includes(category)||title.length<3||title.length>120||description.length<3||description.length>4000){toast('Revisa los campos del reporte.','bad');return}S.betaSubmitting=true;const send=$('#submitBetaFeedback');if(send){send.disabled=true;send.setAttribute('aria-busy','true');send.textContent='Enviando…'}try{await jreq('/rest/v1/beta_feedback',{method:'POST',headers:{Prefer:'return=minimal'},body:JSON.stringify({user_id:S.user.id,category,title,description,page:location.hash||'#home',browser_info:navigator.userAgent.slice(0,500)})});let message='Reporte recibido correctamente.';try{await loadBetaFeedback()}catch(e){message='Reporte guardado, pero no se pudo actualizar el listado. Usa Actualizar reportes.'}render();toast(message,'ok')}catch(e){toast(friendlyError(e),'bad')}finally{S.betaSubmitting=false;const btn=$('#submitBetaFeedback');if(btn){btn.disabled=false;btn.removeAttribute('aria-busy');btn.textContent='Enviar reporte →'}}}
async function saveBetaAdminReport(id,button){if(!S.admin||!id)return;const status=$$('[data-beta-edit-status]').find(el=>el.dataset.betaEditStatus===id)?.value,priority=$$('[data-beta-edit-priority]').find(el=>el.dataset.betaEditPriority===id)?.value,admin_note=$$('[data-beta-edit-note]').find(el=>el.dataset.betaEditNote===id)?.value.trim()||'';if(!['open','reviewing','resolved','dismissed'].includes(status)||!['low','normal','high','critical'].includes(priority)||admin_note.length>4000){toast('Revisa los datos del reporte.','bad');return}const previous=(S.adminBetaFeedback||[]).find(f=>f.id===id);if(!previous)return;button.disabled=true;button.textContent='Guardando…';try{const changed=previous.status!==status||previous.priority!==priority||String(previous.admin_note||'')!==admin_note;if(!changed){toast('No hay cambios por guardar.');return}await jreq(`/rest/v1/beta_feedback?id=eq.${encodeURIComponent(id)}`,{method:'PATCH',headers:{Prefer:'return=representation'},body:JSON.stringify({status,priority,admin_note:admin_note||null,updated_at:new Date().toISOString()})});try{await audit('feedback_updated','beta_feedback',id,{status,priority,changed_status:previous.status!==status,changed_priority:previous.priority!==priority,changed_note:String(previous.admin_note||'')!==admin_note})}catch(err){console.warn('No se pudo registrar la auditoría Beta',err)}await loadAdminData();render();toast('Reporte actualizado.','ok')}catch(e){toast(friendlyError(e),'bad')}finally{button.disabled=false;button.textContent='Guardar cambios'}}
