let deferredInstallPrompt=null;
async function installPwa(){
 if(deferredInstallPrompt){
  const prompt=deferredInstallPrompt;deferredInstallPrompt=null;
  await prompt.prompt();
  try{await prompt.userChoice}catch{}
  S.pwaInstallReady=false;render();return;
 }
 if(window.matchMedia('(display-mode: standalone)').matches||navigator.standalone){toast('El Obi del Lector ya está abierto como aplicación.','ok');return}
 const ios=/iPad|iPhone|iPod/.test(navigator.userAgent)||navigator.platform==='MacIntel'&&navigator.maxTouchPoints>1;
 const message=ios?'En Safari: toca Compartir (cuadrado con flecha hacia arriba), elige «Añadir a pantalla de inicio» y confirma «Añadir». Si no aparece, busca la opción en el menú de acciones de Compartir.':'En tu navegador, abre el menú (⋮ o equivalente), elige «Instalar aplicación» o «Añadir a pantalla de inicio» y confirma. Si el navegador no ofrece esa opción, abre NLOBI desde Chrome o Safari.';
 const dialog=document.createElement('dialog');dialog.className='installHelpDialog';
 dialog.innerHTML='<div class="installHelpHead"><strong>Instalar El Obi del Lector</strong><button type="button" aria-label="Cerrar instrucciones">✕</button></div><p></p><button class="btn primary" type="button">Entendido</button>';
 dialog.querySelector('p').textContent=message;
 dialog.querySelectorAll('button').forEach(btn=>btn.addEventListener('click',()=>dialog.close()));
 dialog.addEventListener('close',()=>dialog.remove(),{once:true});
 document.body.appendChild(dialog);dialog.showModal();
}

async function loadPublicProfileData(id){
 const rows=await jreq(`/rest/v1/profiles?id=eq.${id}&select=id,username,display_name,avatar_url,banner_url,bio,public_library,public_activity&limit=1`);
 const p=rows?.[0];if(!p)throw new Error('Perfil no encontrado.');
 let library=[],activity=[];
 if(p.public_library){library=await jreq(`/rest/v1/library_entries?user_id=eq.${id}&select=translation_id,status,is_favorite,translations(id,title,status,novels(id,title,cover_url),translator_groups(id,name))&order=updated_at.desc&limit=50`)||[];library=library.filter(x=>x.translations&&['active','complete','paused'].includes(x.translations.status))}
 if(p.public_activity)activity=await jreq(`/rest/v1/reading_progress?user_id=eq.${id}&select=translation_id,progress_percent,updated_at,translations(id,title,novels(id,title))&order=updated_at.desc&limit=20`)||[];
 const reviews=await jreq('/rest/v1/rpc/get_public_reader_reviews',{method:'POST',body:JSON.stringify({p_user_id:id})})||[];
 return {...p,library,activity,reviews}
}
async function loadPublicGroupData(id){
 const rows=await jreq(`/rest/v1/translator_groups?id=eq.${id}&select=id,slug,name,description,avatar_url,banner_url,primary_color,secondary_color&limit=1`);
 const g=rows?.[0];if(!g)throw new Error('Equipo no encontrado.');
 const [translations,support,stats]=await Promise.all([
  jreq(`/rest/v1/translations?group_id=eq.${id}&status=in.(active,complete,paused)&select=id,title,status,language_code,novels(id,title,synopsis,cover_url,author_name,genres),translator_groups(id,name)&order=updated_at.desc`),
  jreq(`/rest/v1/support_links?group_id=eq.${id}&select=id,label,url&order=created_at.asc`),
  jreq('/rest/v1/rpc/get_public_translator_group_stats',{method:'POST',body:JSON.stringify({p_group_id:id})})
 ]);
 const own=new Map((translations||[]).map(x=>[x.id,x])),volumeMap=new Map((S.publishedVolumes||[]).filter(v=>own.has(v.translation_id)).map(v=>[v.id,v]));
 const published=[...(S.publishedVolumes||[]).filter(v=>own.has(v.translation_id)&&v.status==='published').map(v=>({type:'volume',translation_id:v.translation_id,translation_title:titleOf(own.get(v.translation_id)),volume_number:v.volume_number,published_at:v.published_at})),...(S.publishedSections||[]).filter(sec=>volumeMap.has(sec.volume_id)&&sec.status==='published').map(sec=>{const v=volumeMap.get(sec.volume_id);return{type:'chapter',translation_id:v.translation_id,translation_title:titleOf(own.get(v.translation_id)),title:sec.title,volume_number:v.volume_number,published_at:sec.published_at}})].filter(x=>x.published_at&&Date.parse(x.published_at)<=Date.now()).sort((a,b)=>Date.parse(b.published_at)-Date.parse(a.published_at));
 return {...g,translations:translations||[],support_links:support||[],stats:stats?.[0]||{},recent_publications:published}
}
async function loadReaderRouteData(sectionId,translationId=null,{record=true}={}){
 if(!navigator.onLine){
  const cached=readCachedChapter(sectionId);if(!cached)throw new Error('Este capítulo no está disponible sin conexión todavía.');
  S.readerSection=cached;S.readerComments=[];return cached
 }
 const secRows=await jreq(`/rest/v1/sections?id=eq.${sectionId}&status=eq.published&select=id,volume_id,title,section_type,section_number,content&limit=1`);
 const sec=secRows?.[0];if(!sec)throw new Error('El capítulo no está disponible.');
 const volRows=await jreq(`/rest/v1/volumes?id=eq.${sec.volume_id}&status=eq.published&select=id,translation_id,volume_number,title,epub_font_url,epub_font_family,epub_fonts&limit=1`);
 const vol=volRows?.[0];if(!vol)throw new Error('El volumen no está disponible.');
 const trId=translationId||vol.translation_id,tr=await loadTranslationDetail(trId);if(!tr)throw new Error('La obra no está disponible.');
 const navigation=(tr.volumes||[]).filter(v=>v.status==='published').sort((a,b)=>Number(a.volume_number)-Number(b.volume_number)).flatMap(v=>(v.sections||[]).filter(x=>x.status==='published').sort((a,b)=>(a.sort_order||0)-(b.sort_order||0)).map(x=>({...x,volume_id:v.id,volume_number:v.volume_number})));
 S.readerSection={...sec,translation_id:trId,volume_number:vol.volume_number,novel_title:tr.novels?.title,navigation,epub_font_url:vol.epub_font_url,epub_font_family:vol.epub_font_family,epub_fonts:vol.epub_fonts?.length?vol.epub_fonts:(vol.epub_font_url?[{url:vol.epub_font_url,family:vol.epub_font_family||'Original',style:'normal',weight:'normal'}]:[])};if(S.readerSection.epub_fonts.length)activateEpubFonts(S.readerSection.epub_fonts);
 cacheReaderChapter(S.readerSection);
 if(record&&S.user){await recordReadingHistory(sectionId,trId);await saveReaderProgress(nonRegressingPercent(currentReaderPercent(false)),false)}
 return S.readerSection
}
async function resolveDynamicRoute(route=S.view){
 if(!route||!navigator.onLine&& !route.startsWith('reader:'))return;
 const parts=route.split(':'),kind=parts[0],id=parts.slice(kind==='studio'?2:1).join(':');
 if(kind==='detail'){

  if(S.currentDetail?.id!==id)S.currentDetail=await loadTranslationDetail(id);
  if(!S.currentDetail)throw new Error('Obra no encontrada.');
  if(S.detailReviewsFor!==id)await loadTranslationReviews(id);
 }else if(kind==='group'){
  if(S.publicGroup?.id!==id)S.publicGroup=await loadPublicGroupData(id);
 }else if(kind==='profile'){
  if(S.publicProfile?.id!==id)S.publicProfile=await loadPublicProfileData(id);
 }else if(kind==='reader'){
  if(S.readerSection?.id!==id)await loadReaderRouteData(id,null,{record:true});
 }else if(route.startsWith('studio:project:')){
  if(!S.user)throw new Error('Inicia sesión para abrir Studio.');
  if(S.studioProject?.id!==id)S.studioProject=await loadStudioProject(id);
  if(!S.studioProject)throw new Error('Proyecto no disponible.');
 }else if(route.startsWith('studio:team:')){
  if(!S.user)throw new Error('Inicia sesión para abrir Studio.');
  if(S.studioTeam?.id!==id){S.studioTeam=await loadStudioTeam(id);if(!S.studioTeam)throw new Error('Equipo no disponible.');await loadTeamMembers(id)}
 }else if(route.startsWith('studio:media:')){
  if(!S.user)throw new Error('Inicia sesión para abrir Studio.');
  if(S.mediaGroupId===id&&S.mediaLoading)return;
  S.mediaGroupId=id;S.mediaTarget=null;S.mediaQuery='';S.mediaPage=0;S.mediaUsage={};S.mediaLoading=true;render();
  try{S.mediaFiles=await storageWalk(`teams/${id}`);await loadMediaUsage(S.mediaFiles.map(x=>x.path))}finally{S.mediaLoading=false}
 }
}
function restoreReaderRouteFromCache(){if(!S.view.startsWith('reader:')||S.readerSection)return;const id=S.view.split(':')[1],cached=readCachedChapter(id);if(cached){S.readerSection=cached;S.readerComments=[]}}
function registerPwa(){
 if(!('serviceWorker'in navigator)||!location.protocol.startsWith('http'))return;
 let refreshing=false;
 navigator.serviceWorker.addEventListener('controllerchange',()=>{if(refreshing)return;refreshing=true;location.reload()});
 navigator.serviceWorker.register('/sw.js',{updateViaCache:'none'}).then(reg=>{
  reg.update().catch(()=>{});
  reg.addEventListener('updatefound',()=>{const w=reg.installing;if(!w)return;w.addEventListener('statechange',()=>{if(w.state==='installed'&&navigator.serviceWorker.controller)toast('Nueva versión de El Obi del Lector instalada. Actualizando…','ok')})})
 }).catch(e=>console.warn('SW',e))
}
window.addEventListener('beforeinstallprompt',e=>{e.preventDefault();deferredInstallPrompt=e;S.pwaInstallReady=true;render()});
window.addEventListener('appinstalled',()=>{deferredInstallPrompt=null;S.pwaInstallReady=false;toast('El Obi del Lector quedó instalado.','ok');render()});
async function boot(isRetry=false){S.admin=false;S.catalogLoading=true;if(localStorage.getItem('nlobi_dark')==='1')document.body.classList.add('dark');S.view=routeFromHash();restoreReaderRouteFromCache();setNetworkBadge();render();try{if(navigator.onLine){await loadCatalog();await loadRatings();S.catalogLoaded=true;S.err='';if(S.token){try{await ensureFreshSession();await loadUser();await loadRatings();await flushProgressQueue()}catch(e){clearSession();S.user=S.profile=null;console.warn('Sesión no renovable',e)}}await resolveDynamicRoute(S.view);if(isRetry)toast('Conexión restablecida.','ok')}else{await resolveDynamicRoute(S.view);S.err=''}}catch(e){S.err=friendlyError(e,'No se pudo cargar la información en este momento.');console.error(e)}finally{S.catalogLoading=false}render();const notice=sessionStorage.getItem('nlobi_auth_notice');if(notice){sessionStorage.removeItem('nlobi_auth_notice');const bad=notice.startsWith('error:'),msg=notice.slice(notice.indexOf(':')+1);toast(bad?'No se pudo confirmar el correo: '+msg:msg,bad?'bad':'ok')}}
// Mantener lanzamientos sincronizados sin reordenar la interfaz durante la lectura.
let releasesRefreshPending=false,lastReleasesRefresh=0;
async function refreshPublicReleases(force=false){
 if(releasesRefreshPending||!navigator.onLine||document.hidden||S.catalogLoading)return;
 if(!['home','releases'].includes(S.view)&&!S.view.startsWith('collection:'))return;
 if(!force&&Date.now()-lastReleasesRefresh<60000)return;
 releasesRefreshPending=true;
 try{
  await loadCatalog();
  lastReleasesRefresh=Date.now();
  if(['home','releases'].includes(S.view)||S.view.startsWith('collection:'))render();
 }catch(error){console.warn('No se pudieron actualizar los lanzamientos',error)}
 finally{releasesRefreshPending=false}
}
document.addEventListener('visibilitychange',()=>{if(!document.hidden)refreshPublicReleases(true)});
window.addEventListener('focus',()=>refreshPublicReleases());
window.setInterval(()=>refreshPublicReleases(),60000);
let featuredPauseUntil=0;
window.setInterval(()=>{if(S.view!=='home'||document.hidden||Date.now()<featuredPauseUntil||window.matchMedia('(prefers-reduced-motion: reduce)').matches)return;const n=S.catalog.filter(x=>x.novels?.cover_url&&!x.demo).slice(0,8).length;if(n<2)return;S.featuredIndex=((S.featuredIndex||0)+1)%n;render()},6500);
window.addEventListener('hashchange',async()=>{pendingRouteFocus=true;S.view=routeFromHash();render();window.scrollTo({top:0,behavior:'smooth'});try{await resolveDynamicRoute(S.view);S.err=''}catch(e){S.err=friendlyError(e,'No se pudo abrir esta vista.');console.error(e)}render()});
window.addEventListener('online',async()=>{S.online=true;setNetworkBadge();toast('Conexión restablecida.','ok');await flushProgressQueue();boot(true)});
window.addEventListener('offline',()=>{S.online=false;setNetworkBadge();render();toast('Sin conexión. Los capítulos guardados siguen disponibles.','bad')});
window.addEventListener('error',e=>{console.error('[NLOBI global error]',e.error||e.message,e.filename||'',e.lineno||'',e.colno||'')});
window.addEventListener('unhandledrejection',e=>{console.error('[NLOBI unhandled rejection]',e.reason)});
if(CONFIG.qaMode===true){
 window.__NLOBI_QA__={
  setState(patch={}){Object.assign(S,patch);render()},
  setView(view){S.view=validRoute(view)?view:'home';history.replaceState(null,'','#'+S.view);render()},
  getState(){return S},
  parseEpub(file){return parseEpubRich(file)},
  mediaUrl(url){return safeMediaUrl(url)},
  detectImportSections(blocks,text=''){return detectSectionsRich(blocks,text)}
 }
}
consumeAuthCallback();
if(!location.hash)history.replaceState(null,'','#home');
registerPwa();
boot();